import type { CSSProperties } from "react";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { Text } from "@/shared/ui/typography/Text";

function rateLimitedUntil(e: unknown): number | null {
  const m = /github rate-limited until (\d+)/.exec(String(e));
  return m ? Number(m[1]) * 1000 : null;
}
function rateLimitNote(e: unknown): string | null {
  const until = rateLimitedUntil(e);
  if (until === null) return null;
  const at = new Date(until).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  return `GitHub rate limit reached — showing cached data; retrying after ${at}.`;
}
export function QueryBanner({ error = "Something went wrong fetching the project board.", style }: { error?: string | null; style?: CSSProperties }) {
  if (!error) return null;
  const note = rateLimitNote(error);
  if (note) {
    return (
      <Text as="div" mono size={11} tone="dim" style={{ padding: "12px 16px", ...style }}>
        {note}
      </Text>
    );
  }
  return (
    <InlineError pad={[12, 16]} radius={6} style={style}>{error}</InlineError>
  );
}
